-- ==============================================================================
-- RETRO Qatar — Master Database Seed (All 375 Products)
-- Includes:
-- 1. All PC Components, Gaming PCs & Hardware (118 products)
-- 2. Official PDF Catalog (57 products)
-- 3. Complete Verified Inventory (200 products)
--
-- Instructions: Copy and paste this whole script into the Supabase SQL Editor and click RUN.
-- ==============================================================================

-- 1. Enable Extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. Create products table if it doesn't exist
CREATE TABLE IF NOT EXISTS products (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    sku VARCHAR(100) UNIQUE NOT NULL,
    barcode VARCHAR(100),
    name_en VARCHAR(255) NOT NULL,
    name_ar VARCHAR(255) NOT NULL,
    description_en TEXT,
    description_ar TEXT,
    category VARCHAR(100) NOT NULL,
    sub_category VARCHAR(100),
    main_category VARCHAR(100),
    section VARCHAR(100),
    source VARCHAR(50) DEFAULT 'POS',
    brand VARCHAR(100),
    model VARCHAR(100),
    condition VARCHAR(50) DEFAULT 'New',
    cost_price DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    selling_price DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    sale_price DECIMAL(10, 2),
    vat_rate DECIMAL(5, 2) DEFAULT 0.00,
    stock_qty INT DEFAULT 0,
    low_stock_threshold INT DEFAULT 1,
    image_url TEXT,
    gallery_urls TEXT[],
    specs JSONB,
    is_digital BOOLEAN DEFAULT FALSE,
    is_featured BOOLEAN DEFAULT FALSE,
    status VARCHAR(50) DEFAULT 'published',
    slug TEXT,
    variations JSONB,
    product_type VARCHAR(100) DEFAULT 'PHYSICAL PRODUCT',
    primary_category VARCHAR(255),
    secondary_category VARCHAR(255),
    platform VARCHAR(100),
    generation VARCHAR(100),
    categories TEXT[],
    tags TEXT[],
    collections TEXT[],
    reserved_qty INT DEFAULT 0,
    available_qty INT DEFAULT 0,
    stock_status VARCHAR(50) DEFAULT 'IN STOCK',
    warranty VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 3. Ensure all columns exist for existing tables
ALTER TABLE products ADD COLUMN IF NOT EXISTS barcode VARCHAR(100);
ALTER TABLE products ADD COLUMN IF NOT EXISTS sub_category VARCHAR(100);
ALTER TABLE products ADD COLUMN IF NOT EXISTS main_category VARCHAR(100);
ALTER TABLE products ADD COLUMN IF NOT EXISTS section VARCHAR(100);
ALTER TABLE products ADD COLUMN IF NOT EXISTS source VARCHAR(50) DEFAULT 'POS';
ALTER TABLE products ADD COLUMN IF NOT EXISTS platform VARCHAR(100);
ALTER TABLE products ADD COLUMN IF NOT EXISTS generation VARCHAR(100);
ALTER TABLE products ADD COLUMN IF NOT EXISTS product_type VARCHAR(100) DEFAULT 'PHYSICAL PRODUCT';
ALTER TABLE products ADD COLUMN IF NOT EXISTS primary_category VARCHAR(255);
ALTER TABLE products ADD COLUMN IF NOT EXISTS secondary_category VARCHAR(255);
ALTER TABLE products ADD COLUMN IF NOT EXISTS specs JSONB;
ALTER TABLE products ADD COLUMN IF NOT EXISTS slug TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS is_featured BOOLEAN DEFAULT FALSE;
ALTER TABLE products ADD COLUMN IF NOT EXISTS status VARCHAR(50) DEFAULT 'published';
ALTER TABLE products ADD COLUMN IF NOT EXISTS stock_qty INT DEFAULT 0;
ALTER TABLE products ADD COLUMN IF NOT EXISTS low_stock_threshold INT DEFAULT 1;
ALTER TABLE products ADD COLUMN IF NOT EXISTS gallery_urls TEXT[];
ALTER TABLE products ADD COLUMN IF NOT EXISTS variations JSONB;
ALTER TABLE products ADD COLUMN IF NOT EXISTS categories TEXT[];
ALTER TABLE products ADD COLUMN IF NOT EXISTS tags TEXT[];
ALTER TABLE products ADD COLUMN IF NOT EXISTS collections TEXT[];
ALTER TABLE products ADD COLUMN IF NOT EXISTS reserved_qty INT DEFAULT 0;
ALTER TABLE products ADD COLUMN IF NOT EXISTS available_qty INT DEFAULT 0;
ALTER TABLE products ADD COLUMN IF NOT EXISTS stock_status VARCHAR(50) DEFAULT 'IN STOCK';
ALTER TABLE products ADD COLUMN IF NOT EXISTS warranty VARCHAR(100);

-- 4. Enable Row Level Security (RLS) and Public Read Access
ALTER TABLE products ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public Read Access" ON products;
CREATE POLICY "Public Read Access"
  ON products
  FOR SELECT
  USING (true);

DROP POLICY IF EXISTS "Public Full Access" ON products;
CREATE POLICY "Public Full Access"
  ON products
  FOR ALL
  USING (true);

-- 5. Insert / Update All 375 Products
